        .container { minheight: 100vh; display: flex; flexdirection: column; alignitems: center; justifycontent: center; padding: 1rem; gap: 1rem; }
        .headerbookingbtn { margintop: 0.2rem; padding: 0.6rem 1.2rem !important; fontsize: 0.9rem !important; }
        .glasscard { background: rgba(28, 28, 30, 0.75); backdropfilter: blur(25px); webkitbackdropfilter: blur(25px); borderradius: 1.5rem; border: 1px solid rgba(255, 255, 255, 0.12); boxshadow: 0 16px 48px rgba(0, 0, 0, 0.3); width: 18rem; height: 18rem; padding: 1rem; display: flex; flexdirection: column; alignitems: center; justifycontent: center; textalign: center; transform: scale(0.49); margintop: 5rem; marginbottom: 5rem; }
        .glasscard h2 { fontsize: 2.2rem; fontweight: 700; marginbottom: 0.5rem; color: fff; }
        .glasscard p { fontsize: 1.6rem; fontweight: 600; color: fff; marginbottom: 1rem; }
        .buttonprimary, .buttonsecondary { border: none; cursor: pointer; transition: transform 0.2s, backgroundcolor 0.2s; fontsize: 1rem; outline: none; webkittaphighlightcolor: transparent; touchaction: manipulation; fontweight: 500; borderradius: 9999px; color: fff; }
        .buttonprimary { background: 0a84ff; padding: 0.875rem 1.75rem; }
        .buttonprimary:hover { transform: scale(1.05); background: 359aff; }
        .buttonprimary:active { transform: scale(0.98); }
        .buttonprimary:disabled { opacity: 0.5; cursor: notallowed; transform: none; }
        .buttonsecondary { background: rgba(255, 255, 255, 0.15); padding: 0.8rem 1.8rem; fontsize: 1.2rem; fontweight: 600; }
        .buttonsecondary:hover { transform: scale(1.05); background: rgba(255, 255, 255, 0.25); }
        .modal { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.5); display: flex; alignitems: center; justifycontent: center; padding: 1rem; zindex: 50; opacity: 0; visibility: hidden; transition: opacity 0.3s ease, visibility 0.3s ease; }
